"""R31 independent judgments, authored from rendered evidence and the frozen contract."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
OUT = ROOT / 'rounds/r31/reports'
C = {f['id']: f for f in json.loads((ROOT/'contract/user-features.json').read_text())['features']}
D = {'round':'R31','evaluator':'/root/review_r31_r34','platforms':{},'feature_observations':{},'journey_observations':{},'findings':[]}

def obs(fid,p,evidence,reason,verified=(),partial=(),missing=(),status='partial'):
    a={}
    for state,keys in [('verified',verified),('partial',partial),('missing',missing)]:
        for key in keys:
            kind,n=key.split(':'); assert int(n)<len(C[fid]['mustKeep'][kind]), (fid,key)
            a[key]={'status':state,'observation':reason}
    D['feature_observations'].setdefault(fid,{})[p]={'status':status,'reason':reason,'evidence':evidence,'assertions':a}

def journey(jid,p,evidence,reason,status='partial'):
    D['journey_observations'].setdefault(jid,{})[p]={'status':status,'reason':reason,'evidence':evidence}

def ep(p,*files,folder='import-complete'):
    return [f'evidence/{p}/{folder}/{f}.json' for f in files]

for p in ['web','mac','android']:
    score = {'new_user':3,'functionality':2.5,'simplicity':2.75,'clarity':2.75 if p=='web' else 2.5,'design':3,'craft':2.75,'originality':3}
    why = {
      'new_user':'The empty home states the purpose and a first import; the revised source list makes device ownership legible. Import context, review, blocked-model setup and return all have a visible next step. Exceptional invitation and cross-page source states still need improvement.',
      'functionality':'The independently exercised import journey now preserves multiline context, blocks dirty confirmation and completes the same task after model configuration on this platform. Shared context and native/Central tasks have substantially more semantic controls and observed transitions, but many required assertions remain partial or untested; the 188-feature completeness anchor is not reached.',
      'simplicity':'Native Sources now uses one source list and task-specific settings disclose secondary controls. Import stays focused. Populated desktop Library retains a long second category rail, while mobile repeats orientation and headings before the first record. Some expanded settings still combine several unrelated tasks.',
      'clarity':('Import state, archive container counts, model module and context versions are substantially clearer. Invitation closure loses the active invitation management entry, and a Markdown file receives audio-style timestamps and speaker labels in processing.' if p=='web' else 'The collection and sending pause scopes can be distinguished, but a source says it is synchronizing while the native destination is still local-only. Android source conflict does not show affected-file holding. These cross-page state contradictions keep clarity below 3.'),
      'design':'A restrained type, spacing and accent system is consistent. Desktop windows and Android bottom navigation adapt coherently; key source rows are visible in the first mobile viewport. Dense library/settings areas keep hierarchy below the highest anchor.',
      'craft':'DOM was captured before viewport screenshots. No browser page errors or horizontal document overflow appeared in the surveyed pages. Stateful corrections work, but invitation reopening and stale native status copy remain interaction defects; full keyboard/accessibility coverage was not performed.',
      'originality':'The separate batch explanation, source context, material attribution, archived-original stages and explicit device ownership form deliberate Mote-specific workflows with familiar controls.'
    }
